mapper.select:
SELECT ID, OPER_TYPE, PROCEDURE_CODE, OPER_STATUS, OPER_REASON, REMARK, CREATE_BY, CREATE_TIME
FROM T_MAINTENANCE_LOG
WHERE 1=1
and OPER_TYPE = #{operType}
and PROCEDURE_CODE = #{procedureCode}
 and INSTR(CREATE_BY, #{createBy}) > 0
 and CREATE_TIME >= STR_TO_DATE(#{startTime},'%Y-%m-%d')
 and CREATE_TIME <= STR_TO_DATE(#{endTime},'%Y-%m-%d %H:%i:%s')

order by CREATE_TIME desc
order by ${orderStr}

mapper.update:
update t_lh_schedule_result r 
update t_cx_schedule_result r 
update t_tm_schedule_result r 
update t_tc_schedule_result r 
update t_nc_schedule_result r 
update t_tq_schedule_result r 
update t_gsq_schedule_result r 
update t_cd15_schedule_result r 
update t_cd90_schedule_result r 
update t_gdyy_schedule_result r 
update t_xwyy_schedule_result r 
set del_flag = NULL
where SCHEDULE_DATE = STR_TO_DATE(#{scheduleDate}, '%Y-%m-%d')

    and SAP_CODE = #{sapCode}
    and exists (select 1 from t_lh_machine_info m where m.MACHINE_CODE = r.LH_MACHINE_CODE and m.id=#{machineId})


    and EMBRYO_CODE = #{materialCode}
    and SAP_CODE = #{sapCode}
    and exists (select 1 from t_cx_machine_info m where m.MACHINE_CODE = r.CX_MACHINE_CODE and m.id=#{machineId})


    and TREAD_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and SIDEWALL_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and LINING_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and BEAD_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and STEEL_RING_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and STEEL_STRIP_CODE1 = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and CLOTH_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)


    and BIG_ROLL_CODE = #{materialCode}


    and BIG_ROLL_CODE = #{materialCode}
    and r.MACHINE_ID = FORMAT(#{machineId}, 0)
